// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != c.owner());
        // Reference: non-owner caller should cause owned() to revert.
        // Bug: owned() always reverts regardless of caller.
        // Both revert here, so this doesn't distinguish them.
        bool refRevert;
        vm.prank(caller);
        try c.owned() { refRevert = false; } catch { refRevert = true; }
        assertTrue(refRevert);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        // Ensure nonOwner is not the default owner (address(this) is the owner by default)
        vm.assume(nonOwner != address(this));
        // nonOwner should never revert on owned() in the reference, but should in the bug.
        // To test: first, we need to make nonOwner the actual owner by transferring ownership.
        // The owner is address(this), so we can call transferOwnership.
        c.transferOwnership(nonOwner);
        // Now nonOwner is the owner in reference. In reference, owned() succeeds; in bug, it always reverts.
        vm.prank(nonOwner);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

